import { TREE_DESCRIPTOR } from './tree.js';
import { VEGETABLE_LAMB_DESCRIPTOR } from './vegetableLamb.js';
import { VOLVELLE_DESCRIPTOR } from './volvelle.js';
import { WAXBLOOM_DESCRIPTOR } from './waxbloom.js';
import { WITNESS_STONE_DESCRIPTOR } from './witnessStone.js';

/** Every descriptor, in editor-display order. */
export const ALL_DESCRIPTORS = [
  TREASURE_CHEST_DESCRIPTOR,
  BUSH_DESCRIPTOR,
  PALIMPSEST_SLAB_DESCRIPTOR,
  ERRATA_SLIP_DESCRIPTOR,
  VOLVELLE_DESCRIPTOR,
  FOOLS_FIRE_DESCRIPTOR,
  OUROBOROS_LOOP_DESCRIPTOR,
  SAINTS_RIB_DESCRIPTOR,
  VEGETABLE_LAMB_DESCRIPTOR,
  SCORIA_ROSE_DESCRIPTOR,
  WAXBLOOM_DESCRIPTOR,
  SCREAMROOT_DESCRIPTOR,
  NULL_LILY_DESCRIPTOR,
  CINDERBLOOM_DESCRIPTOR,
  GILDED_INITIAL_DESCRIPTOR,
  PERIDEXION_TREE_DESCRIPTOR,
  EDEN_MUSHROOM_DESCRIPTOR,
  LISTENER_LICHEN_DESCRIPTOR,
  EDEN_SHROOMLET_DESCRIPTOR,
  WITNESS_STONE_DESCRIPTOR,
  DROWNED_COPYIST_DESCRIPTOR,
  CENSER_SAINT_DESCRIPTOR,
  HALF_DRAWN_OBELISK_DESCRIPTOR,
  SNOWPERSON_DESCRIPTOR,
  GROVE_DESCRIPTOR,
  TREE_DESCRIPTOR,
  HILL_DESCRIPTOR,
  MOUNTAIN_DESCRIPTOR,
  PLAINS_GRASS_DESCRIPTOR,
  MARSH_REEDS_DESCRIPTOR,
  PLATEAU_MOUND_DESCRIPTOR,
  DESERT_SCRUB_DESCRIPTOR,
  BEACH_DRIFTWOOD_DESCRIPTOR,
  KNOT_DESCRIPTOR,
  BASE_DESCRIPTOR,
  CHAMPION_DESCRIPTOR,
  MOB_DESCRIPTOR,
  TRADER_DESCRIPTOR,
  OPEN_TREASURE_CHEST_DESCRIPTOR,
];

/**
 * Descriptors whose home file is not the per-id convention (`<id>.js`).
 * The save server uses this to find an existing object's file; everything not
 * listed here follows the convention.
 */
export const DESCRIPTOR_SOURCES = Object.freeze({
  hill: 'hills.js',
  mountain: 'mountains.js',
  knot: 'knots.js',
  champion: 'champions.js',
  trader: 'traders.js',
  base: 'bases.js',
  mob: 'mobs.js',
});

const byId = new Map(ALL_DESCRIPTORS.map((d) => [d.id, d]));

/** Look up a descriptor by id, or null. */
export function descriptorById(id) {
  return byId.get(id) ?? null;
}
